with feeders as (
    select
        md5(upper('HUB_ASSESSMENT|' || (HUB_ASSESSMENT_BK__RISK_ID))) as HUB_ASSESSMENT_HK
        , RISK_IDENTIFIER as RISK_RULE_NAME
        , VERSION_NO as RULE_VERSION_NUMBER
        , MODULE_ID as RULE_MODULE_IDENTIFIER
        , CATEGORY_CODE as RISK_CATEGORY_CODE
        , SUBCATEGORY_CODE as RISK_SUB_CATEGORY_CODE
        , RISK_SCORE as RULE_CONTRIBUTION_SCORE
        , TRIGGER_TYPE as RULE_TRIGGER_TYPE
        , TRIGGER_LOGIC as RULE_TRIGGER_EXPRESSION
        , RISK_SUSP_FRAUD_ID as SUSPECTED_FRAUD_SCENARIO_REFERENCE
        , RISK_SUSP_FRAUD_DESC as SUSPECTED_FRAUD_SCENARIO_DESCRIPTION
        , START_DATE as RULE_EFFECTIVE_FROM_DATE
        , EXPIRY_DATE as RULE_EFFECTIVE_TO_DATE
        , DEVELOPED_BY as RULE_DEVELOPED_BY_USER_REFERENCE
        , UPDATED_BY as RULE_LAST_MAINTAINED_BY_USER_REFERENCE
        , UPDATED_ON as RULE_LAST_MAINTAINED_TIMESTAMP
        , 'BJAZ_RISK_IDENTIFIERS_MASTER' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_risk_identifiers_master') }}
    where (nullif('RISKRULE:' || nullif(trim(RISK_ID),''), 'RISKRULE:')) is not null
),

resolved as (
    select
        HUB_ASSESSMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RISK_RULE_NAME end) as RISK_RULE_NAME,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_VERSION_NUMBER end) as RULE_VERSION_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_MODULE_IDENTIFIER end) as RULE_MODULE_IDENTIFIER,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RISK_CATEGORY_CODE end) as RISK_CATEGORY_CODE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RISK_SUB_CATEGORY_CODE end) as RISK_SUB_CATEGORY_CODE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_CONTRIBUTION_SCORE end) as RULE_CONTRIBUTION_SCORE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_TRIGGER_TYPE end) as RULE_TRIGGER_TYPE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_TRIGGER_EXPRESSION end) as RULE_TRIGGER_EXPRESSION,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SUSPECTED_FRAUD_SCENARIO_REFERENCE end) as SUSPECTED_FRAUD_SCENARIO_REFERENCE,
