        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_EFFECTIVE_TO_DATE end) as RULE_EFFECTIVE_TO_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_DEVELOPED_BY_USER_REFERENCE end) as RULE_DEVELOPED_BY_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_LAST_MAINTAINED_BY_USER_REFERENCE end) as RULE_LAST_MAINTAINED_BY_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RULE_LAST_MAINTAINED_TIMESTAMP end) as RULE_LAST_MAINTAINED_TIMESTAMP,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_ASSESSMENT_HK
),

hashed as (
    select
        *,
        case when RISK_RULE_NAME is not null or RULE_VERSION_NUMBER is not null or RULE_MODULE_IDENTIFIER is not null or RISK_CATEGORY_CODE is not null or RISK_SUB_CATEGORY_CODE is not null or RULE_CONTRIBUTION_SCORE is not null or RULE_TRIGGER_TYPE is not null or RULE_TRIGGER_EXPRESSION is not null or SUSPECTED_FRAUD_SCENARIO_REFERENCE is not null or SUSPECTED_FRAUD_SCENARIO_DESCRIPTION is not null or RULE_EFFECTIVE_FROM_DATE is not null or RULE_EFFECTIVE_TO_DATE is not null or RULE_DEVELOPED_BY_USER_REFERENCE is not null or RULE_LAST_MAINTAINED_BY_USER_REFERENCE is not null or RULE_LAST_MAINTAINED_TIMESTAMP is not null
                     then md5(upper(coalesce(cast(RISK_RULE_NAME as varchar), '') || '|' || coalesce(cast(RULE_VERSION_NUMBER as varchar), '') || '|' || coalesce(cast(RULE_MODULE_IDENTIFIER as varchar), '') || '|' || coalesce(cast(RISK_CATEGORY_CODE as varchar), '') || '|' || coalesce(cast(RISK_SUB_CATEGORY_CODE as varchar), '') || '|' || coalesce(cast(RULE_CONTRIBUTION_SCORE as varchar), '') || '|' || coalesce(cast(RULE_TRIGGER_TYPE as varchar), '') || '|' || coalesce(cast(RULE_TRIGGER_EXPRESSION as varchar), '') || '|' || coalesce(cast(SUSPECTED_FRAUD_SCENARIO_REFERENCE as varchar), '') || '|' || coalesce(cast(SUSPECTED_FRAUD_SCENARIO_DESCRIPTION as varchar), '') || '|' || coalesce(cast(RULE_EFFECTIVE_FROM_DATE as varchar), '') || '|' || coalesce(cast(RULE_EFFECTIVE_TO_DATE as varchar), '') || '|' || coalesce(cast(RULE_DEVELOPED_BY_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(RULE_LAST_MAINTAINED_BY_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(RULE_LAST_MAINTAINED_TIMESTAMP as varchar), '')))
                end as SAT_ASSESSMENT_RISK_RULE_DEFINITION_HASHDIFF
    from resolved
)

